LEARN.course({id:"metal",family:"Rock",name:"Heavy metal and thrash",tagline:"Palm-muted riffs on a pedal note, gallops and double kick, played loud and tight.",level:"Intermediate",era:"1970 to today",artists:["Black Sabbath","Judas Priest","Iron Maiden","Metallica","Slayer","Megadeth","Anthrax","Candlemass"],listen:["Black Sabbath – Black Sabbath","Iron Maiden – Run to the Hills","Metallica – Master of Puppets","Slayer – Angel of Death","Candlemass – Solitude","Death – Zombie Ritual"],key:"E minor",bpm:160,meter:"4/4",techniques:["palm-muting","gallop","tremolo-picking","alternate-picking"],sources:[{id:"s1",title:"Heavy metal music (summary)",site:"Encyclopaedia Britannica",url:"https://www.britannica.com/summary/heavy-metal-music",kind:"encyclopedia"},{id:"s2",title:"Heavy metal music",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Heavy_metal_music",kind:"encyclopedia"},{id:"s3",title:"Gallop guitar is the metal equivalent of riding to war on horseback, and Iron Maiden are masters of the craft",site:"Guitar World",url:"https://guitarworld.com/lessons/iron-maiden-gallop-guitar",kind:"lesson"},{id:"s4",title:"Thrash metal",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Thrash_metal",kind:"encyclopedia"},{id:"s5",title:"Doom Metal: A Brief Timeline",author:"Jon Wiederhorn",site:"Bandcamp Daily",year:2017,url:"https://daily.bandcamp.com/lists/doom-metal-a-brief-timeline",kind:"article"},{id:"s6",title:"Death metal",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Death_metal",kind:"encyclopedia"},{id:"s7",title:"Gallop Rhythms for Heavy Metal Guitar, Part 1",site:"Guitar World",url:"https://guitarworld.com/lessons/gallop-rhythms-heavy-metal-guitar-part-1",kind:"lesson"},{id:"s8",title:"Building Metal Riffs with the Phrygian Dominant Scale",author:"Simon Revill",site:"Guitar World",url:"https://guitarworld.com/lessons/building-metal-riffs-phrygian-dominant-scale",kind:"lesson"},{id:"s9",title:"Using Pedals to Shape High-Gain Amp Tones",site:"Reverb",url:"https://reverb.com/news/using-pedals-to-shape-high-gain-amp-tones",kind:"article"},{id:"s10",title:"In praise of the 1984-85 Mesa/Boogie Mark IIC+, the high-gain boutique amp behind rock and metal's holy grail tones",site:"Guitar World",url:"https://guitarworld.com/features/mesa-boogie-mark-iic-1984-1985",kind:"article"},{id:"s11",title:"Thrash Metal Drumming",author:"Ryan Alexander Bloom",site:"Independently published",year:2020,url:"https://betterread.com.au/book/thrash-metal-drumming.do",kind:"book"},{id:"s12",title:"Drop tunings",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Drop_tunings",kind:"encyclopedia"},{id:"s13",title:"15 Bands Considered Pioneers of Thrash Metal",author:"Lauryn Schaffner",site:"Loudwire",year:2020,url:"https://loudwire.com/bands-pioneered-thrash-metal/",kind:"article"},{id:"s14",title:"A Drummer's Guide To Metal",author:"Brandon Toews",site:"Drumeo",year:2024,url:"https://www.drumeo.com/beat/a-drummers-guide-to-metal/",kind:"lesson"}],study:[{title:"Running with the Devil: Power, Gender, and Madness in Heavy Metal Music",kind:"book",author:"Robert Walser",url:"https://www.schweitzer-online.de/en/buch/Walser/Running-Devil/9780819575142/A23646426/",note:"The standard academic study of metal, including how its riffs, solos and classical borrowings work."},{title:"Sound of the Beast: The Complete Headbanging History of Heavy Metal",kind:"book",author:"Ian Christe",url:"https://openroadmedia.com/ebook/sound-of-the-beast/9780062042989",note:"A readable history of the whole family, from Black Sabbath through thrash, doom and death metal."},{title:"Guitar World's 11 Essential Thrash Metal Albums",kind:"article",author:"Guitar World",url:"https://guitarworld.com/magazine/guitar-worlds-11-essential-thrash-metal-albums",note:"A listening list that traces thrash from Kill 'Em All to Cowboys From Hell."},{title:"Black Sabbath (1970)",kind:"album",author:"Black Sabbath",note:"Where the tritone riff, the slow heavy groove and doom all begin."},{title:"The Number of the Beast (1982)",kind:"album",author:"Iron Maiden",note:"Gallops, twin guitars and soaring classic metal vocals on one record."},{title:"Master of Puppets (1986)",kind:"album",author:"Metallica",note:"The reference for palm-muted thrash rhythm guitar and the Mark IIC+ sound."},{title:"Double Bass Drumming",kind:"book",author:"Joe Franco",note:"A long-standing method for the drummer in your band who needs double-kick endurance."},{title:"Using Drop-D Tuning to Write Heavy Riffs",kind:"lesson",author:"Metal Mike Chlasciak",url:"https://www.guitarworld.com/lessons/metal-life-metal-mike-using-drop-d-tuning-write-heavy-riffs",note:"Riff-writing ideas for drop D from a working metal guitarist."}],steps:[{id:"sound",title:"The sound: riffs, volume and weight",body:"Heavy metal is rock built on loud, distorted power chords, a hard beat and a thumping bass, often with dark lyrics. Songs are usually built on riffs, and the guitar solo is treated as an essential part of the style.\n\nBlack Sabbath's 1970 debut laid the foundation for the heaviest end of the style, and their records pushed 1970s bands toward downtuned, heavily distorted, dirge-like music. In the early 1980s, thrash bands took the double bass drumming and complex guitar work of the new wave of British heavy metal, the movement that included Iron Maiden, and fused it with the speed, attitude and aggression of punk and hardcore. Metallica, Slayer, Megadeth and Anthrax became thrash's **Big Four**, with a commercial peak from roughly 1985 to 1991.\n\nThis course covers classic heavy metal and thrash, the shared ground that most later styles grew from. The map below is only a quick orientation.",cites:["s1","s2","s4","s5","s13"],blocks:[{type:"callout",tone:"history",text:"A quick map. The **new wave of British heavy metal** fed double bass drumming and complex guitar work into what came next. **Thrash** (early 1980s) is fast, palm-muted and double-kicked. **Doom** keeps Sabbath's slow tempos, fuzz, repetition and groove; Pentagram, Saint Vitus and Candlemass built it up through the 1970s and 1980s. **Death metal** (Possessed, Death, Morbid Angel and others in the 1980s) tunes lower and adds growled vocals, tremolo picking and blast beats.",cites:["s4","s5","s6","s14"]}]},{id:"harmony",title:"Harmony: modes, pedal points and the tritone",body:"Most metal riffs come from two modes. **Aeolian** (natural minor) gives progressions like i, bVI, bVII. **Phrygian** adds a flat second, so a riff that rocks between i and bII gets its menace from a single half step.\n\nThe bass often stays put. A **pedal point** is a sustained low note with other notes or chords moving above it, and metal uses pedal points as a harmonic basis: the open low E chugs while fretted notes jump around it.\n\nThe **tritone**, which medieval theorists called *diabolus in musica*, appears in many metal riffs alongside tense chromatic moves. In E, that note is Bb.\n\nFor a more exotic colour, players borrow **Phrygian dominant**, the scale you get by playing harmonic minor from its fifth note. Its flat second, major third and flat seventh give it an Eastern sound. The power chords underneath are just root and fifth, sometimes with the octave, and played low through heavy distortion they add weight.",cites:["s2","s8"],blocks:[{type:"progression",name:"Aeolian power-chord loop",chords:"i5 bVI5 bVII5 i5",note:"E5, C5, D5, E5. The classic minor-key climb."},{type:"progression",name:"Phrygian half step",chords:"i5 bII5 i5 bII5",note:"E5 to F5 and back. Slow and sustained for doom, fast and palm-muted for thrash."},{type:"progression",name:"Tritone pull",chords:"i5 - bV5 -",note:"E5 to Bb5: the tritone as a chord change. Let it fall back to E5."},{type:"shapes",title:"Power chords on the low strings",shapes:[{name:"E5",frets:"0 2 2 x x x"},{name:"F5",frets:"1 3 3 x x x"},{name:"G5",frets:"3 5 5 x x x"},{name:"Bb5",frets:"6 8 8 x x x"}],note:"Root and fifth with the octave on top. Mute the other strings with the side of your fretting finger."},{type:"scale",root:"E",scale:"phrygian",view:"all",note:"E Phrygian: the F, one fret above the open string, is the sound to aim for."},{type:"scale",root:"E",scale:"phrygDom",view:"all",note:"E Phrygian dominant is A harmonic minor played from E. The G# gives it its exotic edge."},{type:"tab",id:"metal-pedal-riff",title:"Pedal-point riff with a tritone",instr:"guitar",bpm:140,grid:4,tone:"metal-rhythm",notes:[[0,6,0,1,"pm,D"],[1,6,0,1,"pm,U"],[2,6,1,1,"D"],[3,6,0,1,"pm,U"],[4,6,0,1,"pm,D"],[5,6,3,1,"U"],[6,6,0,1,"pm,D"],[7,6,0,1,"pm,U"],[8,6,6,1,"D,acc"],[9,6,0,1,"pm,U"],[10,6,0,1,"pm,D"],[11,6,5,1,"U"],[12,6,0,1,"pm,D"],[13,6,3,1,"U"],[14,6,1,1,"D"],[15,6,0,1,"pm,U"],[16,6,0,1,"pm,D"],[17,6,0,1,"pm,U"],[18,6,1,2,"D,acc"],[18,5,3,2,"D,acc"],[20,6,0,1,"pm,D"],[21,6,0,1,"pm,U"],[22,6,6,2,"D,acc"],[22,5,8,2,"D,acc"],[24,6,0,1,"pm,D"],[25,6,0,1,"pm,U"],[26,6,5,2,"D"],[26,5,7,2,"D"],[28,6,3,2,"D"],[28,5,5,2,"D"],[30,6,1,2,"D"],[30,5,3,2,"D"]],note:"The open E is the pedal. Bar 1 visits F (the Phrygian flat second) and Bb (the tritone); bar 2 turns them into power chords and walks down to F5, which pulls back to E."}]},{id:"rhythm",title:"Rhythm and drums: gallops, skank beats and double kick",body:"Thrash drumming relies on speed and a driving beat, and double bass drumming is one of its core features: two bass drums or a double pedal let the kick roll continuous sixteenths under the band. Drum teachers treat double bass as one of the essential elements of metal drumming in general.\n\nThree feels cover a lot of ground. The **gallop** puts an eighth note and two sixteenths in each beat, and a drummer can double it on the kick so guitar and drums gallop together. The **skank beat** is a punk-rooted pattern that thrash drum methods teach alongside double-time and double-bass feels; in the version below, kick and snare alternate on fast eighths under steady hi-hats. The **double-kick drive** keeps the snare on 2 and 4 while the feet play sixteenths, which makes a chorus feel bigger without changing the tempo.\n\nWhatever the feel, lock the kick to your palm-muted rhythm. When the drummer's feet follow the riff, the whole band hits as one.",cites:["s4","s7","s11","s14"],blocks:[{type:"groove",groove:{id:"metal-gallop-kick",name:"Gallop with the kick",role:"Verse",steps:16,beats:4,meter:"4/4",swing:0,t:{hh:"x.x.x.x.x.x.x.x.",sn:"....x.......x...",kk:"x.xxx.xxx.xxx.xx"}},note:"The kick plays the gallop (one eighth, two sixteenths) on every beat, matching the guitar."},{type:"groove",groove:{id:"metal-skank",name:"Thrash skank beat",role:"Verse",steps:16,beats:4,meter:"4/4",swing:0,t:{cr:"x...............",hh:"..x.x.x.x.x.x.x.",sn:"..x...x...x...x.",kk:"x...x...x...x..."}},note:"Kick on the beat, snare on every off-beat eighth. Play it fast, around 180 to 200 bpm, for a thrash verse."},{type:"groove",groove:{id:"metal-double-kick",name:"Double-kick drive",role:"Chorus",steps:16,beats:4,meter:"4/4",swing:0,t:{cr:"x...............",rd:"..x.x.x.x.x.x.x.",sn:"....x.......x...",kk:"xxxxxxxxxxxxxxxx"}},note:"Continuous sixteenths on the feet with a plain backbeat on top."}]},{id:"techniques",title:"Guitar techniques: mute, gallop, tremolo",body:"Thrash rhythm guitar uses heavy distortion and power chords, and it is often palm muted for a tighter, more precise sound. Rest the edge of your pick hand on the strings right at the bridge saddles. Too far toward the neck and the note dies; too far back and it rings open.\n\nIron Maiden made the **gallop** a signature, with a feel often compared to riding into battle. It is an eighth note followed by two sixteenths, which is easy to confuse with a triplet. Count it 1, &, a.\n\n**Tremolo picking** is fast, continuous alternate picking. Thrash players use it in solos, and death metal uses it for whole riffs.\n\nMany players tune the low string down to **drop D**. The bottom three strings then give a power chord under one finger, the open strings give a D5, and you get a heavier, darker sound without retuning all six strings.",cites:["s3","s4","s6","s7","s12"],blocks:[{type:"technique",id:"palm-muting",note:"Thrash chugs live here. Keep every muted note the same length and volume."},{type:"technique",id:"gallop",note:"Count each beat as 1, &, a: one eighth, then two sixteenths. Pick down, down, up."},{type:"tab",id:"metal-gallop-riff",title:"Gallop riff in E minor",instr:"guitar",bpm:160,grid:4,tone:"metal-rhythm",notes:[[0,6,0,2,"pm,D"],[2,6,0,1,"pm,D"],[3,6,0,1,"pm,U"],[4,6,0,2,"pm,D"],[6,6,0,1,"pm,D"],[7,6,0,1,"pm,U"],[8,6,3,2,"pm,D"],[8,5,5,2,"pm,D"],[10,6,3,1,"pm,D"],[10,5,5,1,"pm,D"],[11,6,3,1,"pm,U"],[11,5,5,1,"pm,U"],[12,6,5,2,"pm,D"],[12,5,7,2,"pm,D"],[14,6,5,1,"pm,D"],[14,5,7,1,"pm,D"],[15,6,5,1,"pm,U"],[15,5,7,1,"pm,U"],[16,6,0,2,"pm,D"],[18,6,0,1,"pm,D"],[19,6,0,1,"pm,U"],[20,6,0,2,"pm,D"],[22,6,0,1,"pm,D"],[23,6,0,1,"pm,U"],[24,5,3,2,"pm,D"],[24,4,5,2,"pm,D"],[26,5,3,1,"pm,D"],[26,4,5,1,"pm,D"],[27,5,3,1,"pm,U"],[27,4,5,1,"pm,U"],[28,5,5,4,"D,acc"],[28,4,7,4,"D,acc"]],note:"E, E, G5, A5, then E, E, C5 and an open D5. Start at 120 bpm and keep the mute on everything but the last chord."},{type:"technique",id:"tremolo-picking",note:"Use it to carry a melody: each note is picked as fast, even sixteenths."},{type:"tab",id:"metal-tremolo-line",title:"Tremolo-picked harmonic minor line",instr:"guitar",bpm:160,grid:4,notes:[[0,4,9,1,"D"],[1,4,9,1,"U"],[2,4,9,1,"D"],[3,4,9,1,"U"],[4,4,10,1,"D"],[5,4,10,1,"U"],[6,4,10,1,"D"],[7,4,10,1,"U"],[8,4,9,1,"D"],[9,4,9,1,"U"],[10,4,9,1,"D"],[11,4,9,1,"U"],[12,4,7,1,"D"],[13,4,7,1,"U"],[14,4,7,1,"D"],[15,4,7,1,"U"],[16,5,10,1,"D"],[17,5,10,1,"U"],[18,5,10,1,"D"],[19,5,10,1,"U"],[20,5,9,1,"D"],[21,5,9,1,"U"],[22,5,9,1,"D"],[23,5,9,1,"U"],[24,5,6,1,"D"],[25,5,6,1,"U"],[26,5,6,1,"D"],[27,5,6,1,"U"],[28,5,7,4,"D,v"]],note:"B, C, B, A, G, F#, D#, E: E harmonic minor, with the D# leading home. Change notes exactly on the beat while the pick keeps going."},{type:"tuning",name:"Drop D",notes:"D2 A2 D3 G3 B3 E4",note:"Lower only the sixth string a whole step, until it sounds an octave below the open fourth string."},{type:"tab",id:"metal-dropd-riff",title:"Drop D one-finger riff",instr:"guitar",tuning:"D2 A2 D3 G3 B3 E4",bpm:130,grid:4,notes:[[0,6,0,2,"D,acc"],[0,5,0,2,"D,acc"],[0,4,0,2,"D,acc"],[2,6,0,1,"pm,D"],[3,6,0,1,"pm,U"],[4,6,0,1,"pm,D"],[5,6,0,1,"pm,U"],[6,6,3,2,"D"],[6,5,3,2,"D"],[6,4,3,2,"D"],[8,6,0,1,"pm,D"],[9,6,0,1,"pm,U"],[10,6,5,2,"D"],[10,5,5,2,"D"],[10,4,5,2,"D"],[12,6,0,1,"pm,D"],[13,6,6,1,"U"],[13,5,6,1,"U"],[13,4,6,1,"U"],[14,6,5,1,"D"],[14,5,5,1,"D"],[14,4,5,1,"D"],[15,6,0,1,"pm,U"],[16,6,0,2,"D,acc"],[16,5,0,2,"D,acc"],[16,4,0,2,"D,acc"],[18,6,0,1,"pm,D"],[19,6,0,1,"pm,U"],[20,6,0,1,"pm,D"],[21,6,0,1,"pm,U"],[22,6,3,2,"D"],[22,5,3,2,"D"],[22,4,3,2,"D"],[24,6,0,1,"pm,D"],[25,6,0,1,"pm,U"],[26,6,8,2,"D"],[26,5,8,2,"D"],[26,4,8,2,"D"],[28,6,7,2,"D"],[28,5,7,2,"D"],[28,4,7,2,"D"],[30,6,6,2,"D,acc"],[30,5,6,2,"D,acc"],[30,4,6,2,"D,acc"]],note:"One finger barres frets 3, 5, 6, 7 and 8 across the bottom three strings. The chromatic slide down from Bb5 to Ab5 pulls back to the open D5."}]},{id:"tone",title:"Tone: tight, loud and boosted",body:"Metal guitar tone comes from high volume and heavy distortion, with the amp turned up for punch and grind. The skill is keeping that much gain tight enough for fast palm-muted riffs.\n\nMany players put a Tube Screamer-style overdrive in front of an already high-gain amp, with the drive low and the level high. The pedal adds little distortion of its own. It trims the low end going into the amp and pushes the mids, which balances bass-heavy and treble-heavy amps like a Mesa Rectifier or Peavey 5150 and keeps chugs from going flubby. A noise gate such as a Boss NS-2 or ISP Decimator often sits alongside it.\n\nThe classic thrash sound has a documented reference point. Metallica's James Hetfield and Kirk Hammett used modified Mesa/Boogie Mark IIC+ amps in the mid 1980s, with Aphex EQs and compressor/gates in the effects loop. Use that as a starting direction and trust your ears for the settings.",cites:["s2","s9","s10"],blocks:[{type:"tone",id:"metal-rhythm",name:"Tight thrash rhythm",kind:"electric",guitar:"Solid-body with a bridge humbucker (superstrat, V, Explorer or single-cut style)",pickups:"High-output bridge humbucker, passive or active",strings:"10s in standard; a heavier low string for drop D",amp:"High-gain tube head: Mesa/Boogie Mark-style, Rectifier-style or a boosted British-style amp",settings:{gain:7,bass:6,mid:4,treble:7,presence:6,reverb:1},pedals:["od","eq"],demo:"metal-gallop-riff",tips:["Run a Tube Screamer-style overdrive into the amp with drive near zero and level high. It cuts flab from the low end and adds mid focus, so palm mutes stay tight.","Set the amp gain lower than feels exciting on its own. Gallops and fast riffs need every note to start and stop cleanly.","Add a noise gate (a Boss NS-2 or ISP Decimator type) so the gaps between chugs stay silent.","Shape the final EQ after the preamp. Hetfield and Hammett ran Aphex EQs in the effects loop of their Mark IIC+ amps; an EQ pedal in the loop does a similar job.","For drop D, use a set with a heavier low string so the riff keeps its tension and does not buzz."],cites:["s9","s10","s12"],note:"Play the gallop riff, then switch the overdrive off and on and listen to the low end tighten."}]},{id:"form",title:"Song form: built from riffs",body:"Metal is usually based on riffs, so a song often starts as a pile of riffs and the question of what order they go in. It helps to think of each section as a riff plus a drum feel, and let the chord chart follow from that.\n\nOne workable thrash layout: an intro riff over double kick, a verse over a fast skank beat, a pre-chorus that switches to a gallop, and a chorus where the drums open up. After the second chorus, drop to a half-time riff for contrast, then the guitar solo, which metal treats as an essential part of the song. A last chorus and a hard stop end it.\n\nChange the drum feel or the picking pattern between sections. Two riffs in the same key and tempo can still sound like different parts when one gallops and the other runs over a skank beat. A half-time feel works the same way: the tempo stays put, but the section feels slower and heavier.",cites:["s2","s4","s14"],blocks:[{type:"form",name:"Riff-driven thrash map",sections:[{type:"intro",name:"Main riff",bars:4,chords:"i5 - - bII5",groove:"metal-double-kick",fill:"f-toms"},{type:"verse",bars:8,chords:"i5 bII5 i5 bV5",groove:"metal-skank",fill:"f-snare8"},{type:"pre",bars:4,chords:"bVI5 bVII5",groove:"metal-gallop-kick",fill:"f-build"},{type:"chorus",bars:8,chords:"i5 bVI5 bVII5 i5",groove:"metal-double-kick",fill:"f-toms"},{type:"verse",bars:8,chords:"i5 bII5 i5 bV5",groove:"metal-skank",fill:"f-snare8"},{type:"chorus",bars:8,chords:"i5 bVI5 bVII5 i5",groove:"metal-double-kick",fill:"f-snare16"},{type:"bridge",name:"Half-time riff",bars:8,chords:"i5 - bII5 -",groove:"halftime",fill:"f-build"},{type:"solo",bars:8,chords:"i5 bVI5 bVII5 i5",groove:"metal-gallop-kick",fill:"f-toms"},{type:"chorus",bars:8,chords:"i5 bVI5 bVII5 i5",groove:"metal-double-kick",fill:"f-snare16"},{type:"outro",bars:4,chords:"i5 - bII5 i5",groove:"metal-double-kick",fill:"f-stop"}],note:"Each section has its own drum feel. The half-time riff and the solo give the ear a break before the last chorus."}]},{id:"vocals",title:"Vocals and lyrics",body:"Metal vocals are expected to carry raw emotion, and the tone of the voice can matter more than the words. Styles run from clean singing to the deep growls of death metal.\n\nLyrics often deal with dark and heavy subjects, from personal trauma to wider social issues. Doom drew on occult literature and horror films for its gloomy atmosphere.\n\nFor your verse, write short, punchy lines that sit on the riff's accents. Fast riffs leave little room, so choose words with hard consonants that cut through distortion and save long vowels for the chorus, where the drums open up and the singer has room to hold notes.",cites:["s2","s5","s6"],blocks:[{type:"lyrics",section:"verse",prompt:"Write a four-line verse about facing something bigger than you: a war, a system, an addiction, a storm. Make each line land on the riff accents.",tips:["Put hard consonants (k, t, d, g) on the accented notes so the words cut through distortion.","Keep lines short. A fast riff leaves little room for long sentences.","Save long, open vowels for the chorus, where the drums open up."]}]},{id:"together",title:"Put it together",body:"You now have the parts of a metal song: a pedal-point riff, a gallop, a tremolo line, three drum feels, a tight tone and a riff-based map. Build a short demo from them.\n\nStart with the riffs and the drums together, because in this style the riff and the kick pattern are one idea. Add the vocal line last, once you know where the riffs leave room. Record it at a slower tempo first: tight and steady at 140 bpm sounds heavier than loose at 180.",cites:["s2","s4","s7"],blocks:[{type:"checklist",items:["Write a pedal-point riff on the open low string with a half-step or tritone move.","Play a gallop riff with even palm mutes at 140 bpm before pushing the tempo.","Give every section its own drum feel: skank beat, gallop or double kick.","Set a tight tone: boost in front, gain lower than you think, gate on.","Lay out the song: riffs in order, a half-time riff, a solo and a hard ending.","Write a verse lyric with short, percussive lines."]}]}]}),LEARN.course({id:"metalcore",family:"Rock",name:"Metalcore",tagline:"Drop-tuned chugs locked to the kick drum, harmonised leads, screamed verses and sung choruses.",level:"Intermediate",era:"Late 1990s to today",artists:["Killswitch Engage","Shadows Fall","As I Lay Dying","Trivium","Bullet for My Valentine","Parkway Drive","August Burns Red","Architects"],listen:["At the Gates – Blinded by Fear","Killswitch Engage – My Last Serenade","As I Lay Dying – Confined","Trivium – Pull Harder on the Strings of Your Martyr","Parkway Drive – Carrion","August Burns Red – Composure"],key:"C minor",bpm:150,meter:"4/4",tuning:{name:"Drop C",notes:"C2 G2 C3 F3 A3 D4"},techniques:["palm-muting","alternate-picking","tremolo-picking"],sources:[{id:"c1",title:"Metalcore",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Metalcore",kind:"encyclopedia"},{id:"c2",title:"Melodic metalcore",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Melodic_metalcore",kind:"encyclopedia"},{id:"c3",title:"At the Gates: 'Slaughter of the Soul' (Decibel Hall of Fame No. 2)",author:"J. Bennett",site:"Decibel",year:2005,url:"https://www.decibelmagazine.com/2005/03/01/at-the-gates-slaughter-of-the-soul/",kind:"article"},{id:"c4",title:"Alive Or Just Breathing: how Killswitch Engage saved metal from itself",site:"Louder",url:"https://www.loudersound.com/features/killswitch-engage-story-of-metalcore",kind:"article"},{id:"c5",title:"Breakdown (music)",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Breakdown_(music)",kind:"encyclopedia"},{id:"c6",title:"A Drummer's Guide To Metal",author:"Brandon Toews",site:"Drumeo",year:2024,url:"https://www.drumeo.com/beat/a-drummers-guide-to-metal/",kind:"lesson"},{id:"c7",title:"The Bandcamp Guide to D-Beat",author:"Sims Hardin",site:"Bandcamp Daily",year:2025,url:"https://daily.bandcamp.com/lists/d-beat-album-guide",kind:"article"},{id:"c8",title:"Drop tunings",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Drop_tunings",kind:"encyclopedia"},{id:"c9",title:"Using Pedals to Shape High-Gain Amp Tones",site:"Reverb",url:"https://reverb.com/news/using-pedals-to-shape-high-gain-amp-tones",kind:"article"},{id:"c10",title:"The 7 Best Noise Gate Pedals For Guitar in 2024",author:"Warren Huart",site:"Produce Like A Pro",year:2024,url:"https://producelikeapro.com/blog/best-noise-gate-pedal/",kind:"article"},{id:"c11",title:"Who Invented Metalcore?",author:"Philip Trapp",site:"Loudwire",year:2023,url:"https://loudwire.com/who-invented-metalcore/",kind:"article"},{id:"c12",title:"Drop B Tuning",site:"GuitarTuner.io",url:"https://guitartuner.io/tuning/drop-b",kind:"lesson"},{id:"c13",title:"Disposable Heroes: At the Gates' 'Slaughter of the Soul'",author:"Kevin Stewart-Panko",site:"Decibel",year:2011,url:"https://www.decibelmagazine.com/2011/06/29/disposable-heroes-at-the-gates-slaughter-of-the-soul/",kind:"article"},{id:"c14",title:"Jesse Leach Says Metalcore Became 'Oversaturated,' Names One Band That Stands Out",author:"Lauryn Schaffner",site:"Loudwire",year:2022,url:"https://loudwire.com/killswitch-engage-jesse-leach-metalcore-oversaturated-band-stands-out-architects/",kind:"interview"}],study:[{title:"Slaughter of the Soul (1995)",kind:"album",author:"At the Gates",note:"The melodic death metal record whose riffs and vocals American metalcore bands studied closely."},{title:"Alive or Just Breathing (2002)",kind:"album",author:"Killswitch Engage",note:"Hardcore, thrash and Gothenburg melody on one record: the template for melodic metalcore."},{title:"Ascendancy (2005)",kind:"album",author:"Trivium",note:"Thrash-heavy melodic metalcore with harmonised guitar parts throughout."},{title:"Deep Blue (2010)",kind:"album",author:"Parkway Drive",note:"Low tunings and breakdowns at their most direct."},{title:"Under The Influence: How In Flames Changed Metal",kind:"article",author:"Merlin Alderslade, Metal Hammer",url:"https://www.loudersound.com/features/under-the-influence-how-in-flames-changed-metal",note:"How the Gothenburg sound reached the bands that built metalcore."},{title:"The Evolution of Blast Beats",kind:"video",author:"Derek Roddy",url:"https://hudsonmusic.com/product/the-evolution-of-blast-beats/",note:"A drum method on blast beat types and technique, for your drummer."},{title:"11 Greatest Breakdowns of All Time",kind:"article",author:"Revolver",url:"https://www.revolvermag.com/music/11-greatest-breakdowns-all-time/",note:"A listening list for studying how breakdowns are set up and released."},{title:"Djent-style double kick lesson with Jay Postones",kind:"video",author:"MusicRadar",url:"https://musicradar.com/news/learn-to-play-djent-style-double-bass-drum-patterns-tesseract-jay-postone-free-drum-lesson",note:"A free double-kick lesson from TesseracT's drummer for modern heavy grooves."}],steps:[{id:"sound",title:"The sound: hardcore meets metal",body:"Metalcore fused hardcore punk with heavy metal. It grew out of New York hardcore, and Integrity, which mixed hardcore with metal in the late 1980s, Earth Crisis and Converge are counted among its cornerstones. Its riffs are percussive: stop-start rhythm guitar, heavy palm muting, pick scrapes and dissonant chords, with slow, intense **breakdowns** dropped into the song.\n\nA melodic wave followed. Bands drew on Swedish melodic death metal, especially At the Gates and In Flames. Decibel credits At the Gates' *Slaughter of the Soul* (1995) with carrying the Gothenburg sound to Shadows Fall, Killswitch Engage and many other metal and hardcore crossover bands. Killswitch Engage's *Alive or Just Breathing* (2002) mixed classic hardcore, the thrash of Slayer and early Metallica, and Gothenburg melody, and became the breakthrough record for the style.\n\nIn the 2000s Killswitch Engage, Shadows Fall, As I Lay Dying, Trivium, Bullet for My Valentine and Parkway Drive found mainstream success. The sound you will build here is that melodic metalcore: low, tight chugs, harmonised leads, screamed verses and sung choruses.",cites:["c1","c2","c3","c4","c11"],blocks:[{type:"callout",tone:"history",text:"The melodic wave started before it broke through: Shadows Fall's *Somber Eyes to the Sky* (1997), then Darkest Hour's *The Prophecy Fulfilled* and Unearth's *Above the Fall of Man* (both 1999).",cites:["c2"]}]},{id:"tuning",title:"Low tunings and dark harmony",body:"Most metalcore bands use drop tunings somewhere between Drop D and A, and seven- and eight-string guitars are not unusual. A drop tuning lowers only the lowest string, so a one-finger barre across the bottom three strings makes a power chord.\n\n**Drop C** is Drop D moved a whole step lower: C G C F A D. **Drop B** goes down another whole step to B F# B E G# C#, a tuning associated with bands like August Burns Red, Parkway Drive and Architects.\n\nThe verses and breakdowns live on the open low string, with half-step and tritone moves above it: i to bII, i to bV. A chorus can brighten by leaning on bVI, bIII and bVII, the major chords of the natural minor scale, which give the clean vocal somewhere to rise.",cites:["c1","c8","c12"],blocks:[{type:"tuning",name:"Drop C",notes:"C2 G2 C3 F3 A3 D4",note:"Tune every string down a whole step, then drop the sixth string another whole step to C."},{type:"tuning",name:"Drop B",notes:"B1 F#2 B2 E3 G#3 C#4",note:"A whole step below Drop C. Use heavier strings so the low B holds its pitch."},{type:"progression",name:"Verse and breakdown",chords:"i5 bII5 i5 bV5",note:"C5, Db5, C5, Gb5. Each chord is one finger across the bottom three strings."},{type:"progression",name:"Clean chorus lift",chords:"bVI bIII bVII i",note:"Ab, Eb, Bb, Cm. The major chords of C minor give the sung chorus its lift."},{type:"scale",root:"C",scale:"minor",view:"all",note:"C natural minor. Add Db (the Phrygian flat second) for darker verse riffs."}]},{id:"drums",title:"Drums: d-beat, blast beat and breakdown",body:"Metalcore drumming mixes hardcore and metal, often with double-kick patterns. Three feels do most of the work.\n\nThe **d-beat** is named after the UK punk band Discharge, who turned it into a style of its own: a fast, unrelenting rhythm built for forward momentum. In the version below the snare sits on 2 and 4 while the kick pushes the off-beats and the crash follows the kick. It drives verses forward.\n\nThe **blast beat** is a burst of fast hand and foot strokes tied to extreme metal bands such as Napalm Death and Morbid Angel, and most blasts add double bass. Drum teachers sort them into types such as the traditional, hammer and bomb blast. The version below is a traditional-style blast: kick and snare alternate in sixteenths, with the ride on the kick.\n\nThe **breakdown** is where the song slows into its heaviest part. Drummers usually play it in half time, a simple hand pattern over a busier, syncopated kick. The guitarist chugs on the lowest strings and the kick follows those chugs, usually with quarter notes on a crash or China cymbal and the snare on beat three. At shows, breakdowns are the signal to mosh.",cites:["c1","c5","c6","c7"],blocks:[{type:"groove",groove:{id:"metalcore-dbeat",name:"D-beat verse",role:"Verse",steps:16,beats:4,meter:"4/4",swing:0,t:{cr:"x.....x.x.....x.",hh:"..x.x.....x.x...",sn:"....x.......x...",kk:"x.....x.x.....x."}},note:"Snare on 2 and 4, kick on the syncopated off-beats, crash with every kick."},{type:"groove",groove:{id:"metalcore-blast",name:"Traditional blast",role:"Build",steps:16,beats:4,meter:"4/4",swing:0,t:{rd:"x.x.x.x.x.x.x.x.",sn:".x.x.x.x.x.x.x.x",kk:"x.x.x.x.x.x.x.x."}},note:"Kick and snare alternate every sixteenth; the ride plays with the kick. Use it for short bursts before a chorus."},{type:"groove",groove:{id:"metalcore-breakdown",name:"Half-time breakdown",role:"Bridge & feels",steps:16,beats:4,meter:"4/4",swing:0,t:{cr:"x...x...x...x...",sn:"........x.......",kk:"x..x..x...x.x.xx"}},note:"Quarter notes on the crash, snare on beat three, and the kick copies the guitar chugs of the breakdown riff exactly."}]},{id:"techniques",title:"Guitar techniques: chugs and harmonised leads",body:"Breakdown riffs are palm-muted chugs on the lowest two or three strings. The rests matter as much as the notes: the drummer's kick follows your chugs, so play every one exactly and let the gaps go silent.\n\nFast verse riffs alternate-pick between an open-string pedal and fretted notes on the next strings up. Keep the pick hand loose and the motion small.\n\nThe melodic side comes from Swedish melodic death metal. One Decibel critic hears much of 2000s metalcore as melodic death riffs stitched together with breakdowns, and melodic metalcore keeps the harmonised riffs and tremolo-picked lines. A simple way to harmonise a line is to add a second part a diatonic third above it, one part per guitar. The tab below puts both voices on one guitar so you can hear the result; in a band, each guitarist takes one string.",cites:["c2","c5","c13"],blocks:[{type:"technique",id:"palm-muting",note:"Breakdown chugs sit on the lowest strings. The silence between them is part of the riff."},{type:"tab",id:"metalcore-breakdown-chug",title:"Half-time breakdown in Drop C",instr:"guitar",tuning:"C2 G2 C3 F3 A3 D4",bpm:150,grid:4,tone:"metalcore-gated",notes:[[0,6,0,1,"pm,D"],[3,6,0,1,"pm,D"],[6,6,0,1,"pm,D"],[10,6,0,1,"pm,D"],[12,6,1,2,"D,acc"],[12,5,1,2,"D,acc"],[12,4,1,2,"D,acc"],[14,6,0,1,"pm,D"],[15,6,0,1,"pm,U"],[16,6,0,1,"pm,D"],[19,6,0,1,"pm,D"],[22,6,0,1,"pm,D"],[26,6,0,1,"pm,D"],[28,6,6,2,"D,acc"],[28,5,6,2,"D,acc"],[28,4,6,2,"D,acc"],[30,6,0,1,"pm,D"],[31,6,0,1,"pm,U"]],note:"The chug rhythm matches the kick line of the half-time breakdown groove. Bar 1 hits Db5 (the flat second), bar 2 hits Gb5 (the tritone)."},{type:"technique",id:"alternate-picking",note:"Fast verse riffs jump between the open low string and fretted notes. Strict down-up keeps them even."},{type:"tab",id:"metalcore-verse-riff",title:"Open-string verse riff in Drop C",instr:"guitar",tuning:"C2 G2 C3 F3 A3 D4",bpm:140,grid:4,notes:[[0,6,0,1,"pm,D"],[1,6,0,1,"pm,U"],[2,5,1,1,"D"],[3,6,0,1,"pm,U"],[4,6,0,1,"pm,D"],[5,5,3,1,"U"],[6,6,0,1,"pm,D"],[7,5,1,1,"U"],[8,6,0,1,"pm,D"],[9,6,0,1,"pm,U"],[10,4,0,1,"D"],[11,6,0,1,"pm,U"],[12,5,3,1,"D"],[13,5,1,1,"U"],[14,6,1,1,"D"],[15,6,0,1,"pm,U"],[16,6,0,1,"pm,D"],[17,6,0,1,"pm,U"],[18,5,1,1,"D"],[19,6,0,1,"pm,U"],[20,6,0,1,"pm,D"],[21,5,3,1,"U"],[22,6,0,1,"pm,D"],[23,5,1,1,"U"],[24,4,3,1,"D"],[25,6,0,1,"pm,U"],[26,4,1,1,"D"],[27,6,0,1,"pm,U"],[28,4,0,1,"D"],[29,5,3,1,"U"],[30,5,1,1,"D"],[31,6,1,1,"U"]],note:"C minor with a Db for colour. The muted open C is the pedal; the fretted notes ring a little longer. Play it over the d-beat."},{type:"technique",id:"tremolo-picking",note:"Melodic metalcore borrows tremolo-picked melody lines from melodic death metal. Try the harmony lead below tremolo-picked too."},{type:"tab",id:"metalcore-harmony-lead",title:"Harmonised lead in thirds",instr:"guitar",tuning:"C2 G2 C3 F3 A3 D4",bpm:150,grid:2,tone:"metalcore-gated",notes:[[0,2,10,1,""],[0,1,8,1,""],[1,2,11,1,""],[1,1,10,1,""],[2,2,13,1,""],[2,1,12,1,""],[3,2,15,1,""],[3,1,13,1,""],[4,2,13,1,""],[4,1,12,1,""],[5,2,11,1,""],[5,1,10,1,""],[6,2,10,1,""],[6,1,8,1,""],[7,2,8,1,""],[7,1,6,1,""],[8,2,6,1,""],[8,1,5,1,""],[9,2,8,1,""],[9,1,6,1,""],[10,2,10,1,""],[10,1,8,1,""],[11,2,11,1,""],[11,1,10,1,""],[12,2,10,4,"v"],[12,1,8,4,"v"]],note:"The lower voice (second string) is the melody: G, Ab, Bb, C and back down. The top voice is a diatonic third above in C minor. Two guitarists split the strings."}]},{id:"tone",title:"Tone: tight, gated high gain",body:"Low tunings and high gain make a lot of noise and a lot of low end. Metalcore tone is about control: every chug starts and stops on time.\n\nA Tube Screamer-style pedal in front of the amp, drive low and level high, trims the lows going in and adds mid focus. That balances bass-heavy and treble-heavy amps such as a Rectifier or 5150 and keeps low chugs articulate.\n\nThen gate it. High gain amplifies hiss and hum, and a gate cuts it so the silences in a breakdown stay silent. The ISP Decimator adapts to your playing dynamics, and the Boss NS-2 has a send and return loop for gating the noisiest part of the chain. A faster decay suits tight, rhythmic playing.\n\nLow tunings also need heavier strings, which keep the tension up and stop the low string flopping and buzzing.",cites:["c8","c9","c10","c12"],blocks:[{type:"tone",id:"metalcore-gated",name:"Gated drop-tuned chug",kind:"electric",guitar:"Six-string in Drop C or Drop B, or a seven-string",pickups:"High-output bridge humbucker, active or passive",strings:"Heavier than standard: for Drop B about 12-56 or 11-54, with a 58 or 60 low string if it feels loose",amp:"High-gain American-style head (5150 or Rectifier type)",settings:{gain:7,bass:5,mid:6,treble:6,presence:7,reverb:1},pedals:["od","eq"],demo:"metalcore-breakdown-chug",tips:["Put a Tube Screamer-style overdrive in front with drive low and level high to tighten the low strings.","Use a noise gate. Set the threshold just above the hiss with the guitar silent, and use a fast decay for tight chugs.","If your gate has a send and return loop (as the Boss NS-2 does), put the noisiest gain stages inside it.","Use heavier strings for low tunings so the open low string keeps its pitch under a hard pick attack.","Pick hard and close to the bridge. Metalcore riffs are percussive, and the attack is part of the rhythm."],cites:["c1","c8","c9","c10","c12"],note:"Play the breakdown with the boost off, then on. Listen to the low chugs tighten and the rests get quieter."}]},{id:"form",title:"Song form: verse, chorus, breakdown",body:"Metalcore keeps a recognisable verse and chorus and adds the breakdown as a section of its own. Vocalists usually mix harsh vocals with clean singing, and later bands often switch to the clean voice for the chorus or bridge. That contrast drives the form: fast screamed verses, a sung chorus that opens up, and a breakdown as the heaviest moment.\n\nOne common map runs intro, verse, pre-chorus, chorus, verse, chorus, breakdown, final chorus. A harmonised lead can open the song or return before the last chorus. Breakdowns appear so often that some critics call them overused, and Killswitch Engage's Jesse Leach has said the scene became oversaturated with bands churning out the same big riff, heavy verse and melodic chorus. So make your breakdown earn its place: set it up with a stop or a fill, and come out of it into the biggest chorus of the song.",cites:["c1","c5","c14"],blocks:[{type:"form",name:"Verse, chorus, breakdown",sections:[{type:"intro",name:"Harmony lead",bars:4,chords:"i5 bVI5 bVII5 i5",groove:"metalcore-dbeat",fill:"f-snare16"},{type:"verse",bars:8,chords:"i5 bII5 i5 bV5",groove:"metalcore-dbeat",fill:"f-snare8"},{type:"pre",bars:4,chords:"bVI5 bVII5",groove:"metalcore-blast",fill:"f-build"},{type:"chorus",bars:8,chords:"bVI bIII bVII i",groove:"rock-ride",fill:"f-toms"},{type:"verse",bars:8,chords:"i5 bII5 i5 bV5",groove:"metalcore-dbeat",fill:"f-snare8"},{type:"chorus",bars:8,chords:"bVI bIII bVII i",groove:"rock-ride",fill:"f-stop"},{type:"bridge",name:"Breakdown",bars:8,chords:"i5 - bII5 bV5",groove:"metalcore-breakdown",fill:"f-toms"},{type:"chorus",bars:8,chords:"bVI bIII bVII i",groove:"rock-ride",fill:"f-snare16"},{type:"outro",bars:4,chords:"i5 - - -",groove:"metalcore-breakdown",fill:""}],note:"The stop at the end of the second chorus sets up the breakdown. Swap in Drop B and the same map gets heavier."}]},{id:"vocals",title:"Vocals and lyrics: screamed verse, sung chorus",body:"Early metalcore singers had a raw style somewhere between screaming and shouting. Melodic metalcore added screams and growls alongside clean singing, and the genre often favours positive lyrical content.\n\nWrite the verse and chorus as two voices: the heavy verse and melodic chorus that became the genre's trademark. The screamed verse works like a drum part: short phrases, hard consonants and words that land with the kick. The chorus is the hook, so give it fewer words, longer notes and open vowels a singer can hold over the bVI, bIII, bVII, i progression.",cites:["c1","c2","c14"],blocks:[{type:"lyrics",section:"verse",prompt:"Screamed verse: four short lines about a pressure you are under. Write each line as a rhythm the kick drum could copy.",tips:["Two to five syllables per phrase leaves room to breathe between screams.","Hard consonants at the start of a phrase make the attack line up with the guitar.","Repeat one word or phrase as an anchor the crowd can shout back."]},{type:"lyrics",section:"chorus",prompt:"Clean chorus: answer the verse with a turn toward resolve or hope. Two or three lines with one phrase that repeats.",tips:["Put the longest notes on open vowels (oh, ah, ay).","Use fewer words than the verse; the chorus should feel wider and slower.","Make the title phrase the first or last line so it sticks."]}]},{id:"together",title:"Put it together",body:"Put the pieces in order. Tune down, then write the breakdown first, since it is the moment the rest of the song points to. Next write the fast verse riff, then a clean chorus over the brighter progression, and add the harmonised lead as the intro or pre-chorus.\n\nRecord a rough demo with the grooves from this course and check one thing above all: when the breakdown hits, the guitar chugs and the kick drum should sound like a single instrument.",cites:["c1","c5","c6"],blocks:[{type:"checklist",items:["Tune to Drop C or Drop B and check that your strings hold pitch.","Write a breakdown and have the kick copy every chug.","Write a fast verse riff over the d-beat or a blast beat.","Harmonise a four-bar melody in thirds for the intro or pre-chorus.","Write a clean, singable chorus over bVI, bIII, bVII, i.","Set your gate so the rests between chugs are silent."]}]}]}),LEARN.course({id:"neoclassical",family:"Rock",name:"Neoclassical metal",tagline:"Harmonic minor runs, sweep-picked arpeggios and Baroque pedal points played through a cranked amp.",level:"Advanced",era:"Late 1970s to today",artists:["Ritchie Blackmore","Uli Jon Roth","Randy Rhoads","Yngwie Malmsteen","Jason Becker","Marty Friedman","Vinnie Moore","Tony MacAlpine"],listen:["Deep Purple – Highway Star","Yngwie Malmsteen – Black Star","Yngwie Malmsteen – Far Beyond the Sun","Cacophony – Speed Metal Symphony","Jason Becker – Altitudes"],key:"A minor",bpm:120,meter:"4/4",techniques:["alternate-picking","economy-picking","sweep-picking","vibrato","bends"],sources:[{id:"n1",title:"Neoclassical metal",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Neoclassical_metal",kind:"encyclopedia"},{id:"n2",title:"Shred guitar",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Shred_guitar",kind:"encyclopedia"},{id:"n3",title:"Heavy metal music",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Heavy_metal_music",kind:"encyclopedia"},{id:"n4",title:"Ritchie Blackmore",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Ritchie_Blackmore",kind:"encyclopedia"},{id:"n5",title:"Ritchie Blackmore on Steve Howe, Jimi Hendrix, classical influences and the Bach progression in the Highway Star solo (1973 interview)",author:"Martin K. Webb",site:"Guitar Player",year:2024,url:"https://www.guitarplayer.com/players/ritchie-blackmore-1973-interview",kind:"interview"},{id:"n6",title:"Fretprints: Yngwie Malmsteen",author:"Wolf Marshall",site:"Vintage Guitar",year:2021,url:"https://www.vintageguitar.com/39695/fretprints-yngwie-malmsteen/",kind:"lesson"},{id:"n7",title:"Electric Etudes: Jason Becker",author:"Jamie Humphries",site:"Premier Guitar",year:2014,url:"https://www.premierguitar.com/lessons/electric-etudes-jason-becker",kind:"lesson"},{id:"n8",title:"Eruptions: Heavy Metal Appropriations of Classical Virtuosity",author:"Robert Walser",site:"Popular Music 11.3 (Cambridge University Press)",year:1992,url:"https://www.cambridge.org/core/product/41DD62AC8DF5DC33C9934D3AA81D0EAC",kind:"paper"},{id:"n9",title:"Cram Session: Sweep Picking",author:"Jamie Humphries",site:"Premier Guitar",year:2016,url:"https://www.premierguitar.com/articles/24754-cram-session-sweep-picking",kind:"lesson"},{id:"n10",title:"Frank Gambale",author:"Troy Grady",site:"Cracking the Code",url:"https://troygrady.com/interviews/frank-gambale/",kind:"interview"},{id:"n11",title:"Big Strokes: A Beginner's Guide to Sweep Picking",author:"Charlie Griffiths",site:"Guitar World",year:2015,url:"https://www.guitarworld.com/lessons/big-strokes-beginners-guide-sweepingg",kind:"lesson"},{id:"n12",title:"United Stringdom: Using the Harmonic Minor Scale and Phrygian Dominant Mode to Create Neoclassical Metal-Style Solos",site:"Guitar World",url:"https://www.guitarworld.com/magazine/united-stringdom-using-harmonic-minor-scale-and-phrygian-dominant-mode-create-neoclassical-metal-style-solos",kind:"lesson"},{id:"n13",title:"Yngwie's New Attack!!",author:"Lisa Sharken",site:"Vintage Guitar",year:2004,url:"https://www.vintageguitar.com/2988/yngwie-malmsteen/",kind:"interview"},{id:"n14",title:"How Yngwie Malmsteen Unleashes the Fury",author:"Sam Bell",site:"Premier Guitar",year:2018,url:"https://www.premierguitar.com/lessons/shred/yngwie-malmsteen-guitar-lesson",kind:"lesson"}],study:[{title:"Rising Force (1984)",kind:"album",author:"Yngwie Malmsteen",note:"The album that defined the style: harmonic minor runs, arpeggios and violin-like phrasing."},{title:"Speed Metal Symphony (1987)",kind:"album",author:"Cacophony",note:"Jason Becker and Marty Friedman in synchronised twin-guitar harmony and counterpoint."},{title:"Perpetual Burn (1988)",kind:"album",author:"Jason Becker",note:"Becker's solo debut, full of fast arpeggios and classical writing."},{title:"Machine Head (1972)",kind:"album",author:"Deep Purple",note:"Includes Highway Star, whose solo Blackmore built over a Bach-style progression."},{title:"24 Caprices for solo violin, Op. 1",kind:"book",author:"Niccolò Paganini",url:"https://en.wikipedia.org/wiki/Niccolò_Paganini",note:"The violin showpieces behind the style. Listen to a recording and borrow the phrasing."},{title:"Shredders!: The Oral History of Speed Guitar (and More)",kind:"book",author:"Greg Prato",url:"https://www.schweitzer-online.de/en/buch/Prato/Shredders/9781911036210/A37472980/",note:"Interviews with the players who built the shred and Shrapnel era."},{title:"Monster Licks & Speed Picking",kind:"video",author:"Frank Gambale",note:"Gambale himself teaching the sweep and economy picking approach he is known for."},{title:"Jason Becker: Not Dead Yet (2012)",kind:"video",note:"Documentary on Becker's playing, writing and life with ALS, with interviews from his collaborators."}],steps:[{id:"sound",title:"The sound: Baroque runs at metal volume",body:"Neoclassical metal blends heavy metal with classical music and usually features highly technical playing. Its models are the ornate Baroque style of Vivaldi, Handel and Bach and the showy runs of the violinist Niccolò Paganini.\n\nThe roots are in the 1970s. Ritchie Blackmore, who took a year of classical guitar lessons and is particularly fond of Bach, combined blues phrasing with classical ideas in Deep Purple and Rainbow. Uli Jon Roth's 1970s work with Scorpions is often called a prototype for shred guitar, and Randy Rhoads added neoclassical elements to hard rock and metal.\n\nYngwie Malmsteen, whose main guitar influences were Blackmore and Hendrix, became the style's best-known figure. Shrapnel Records' Mike Varney heard his demo and brought him to the US in 1982, and after short stints in Steeler and Alcatrazz he went solo with *Rising Force* (1984). Shrapnel's mostly instrumental albums drove a golden age in the mid to late 1980s. Varney paired Jason Becker with Marty Friedman in Cacophony, and Becker was 16 when they cut *Speed Metal Symphony*.",cites:["n1","n2","n4","n6","n7"],blocks:[{type:"callout",tone:"history",text:"Blackmore has said the chord progression under his Highway Star solo (Bm, Db, C, G) is a Bach progression. Musicologist Robert Walser, whose 1992 study examines heavy metal's appropriations of classical virtuosity, traces the 1980s spread of 18th-century chord progressions in metal to Blackmore, Rhoads and Malmsteen.",cites:["n3","n5","n8"]}]},{id:"harmony",title:"Harmony: harmonic minor and the diminished chord",body:"The **harmonic minor** scale is the core sound. It is natural minor with a raised seventh: in A minor, G becomes G#. That G# turns the five chord into E7, so V7 to i resolves with a strong pull.\n\nPlay harmonic minor starting from its fifth note and you get **Phrygian dominant** (E F G# A B C D), the exotic sound players use over that E7 chord. Wolf Marshall's study of Malmsteen names these two scales as the uncommon sounds behind his improvising.\n\nThe **diminished seventh** chord is common in the style, and Malmsteen plays it as sequenced arpeggios over the dominant. It is built from stacked minor thirds, so moving it up three frets gives the same four notes, and it can resolve to the tonic as a leading-tone chord: G#°7 to Am is the classic move.\n\nThe progressions below draw on 18th-century habits. Try the first as a plain cadence, the second as a Baroque-style circle of fifths, and the third to hear the diminished chord set up the dominant.",cites:["n1","n6","n8","n12","n14"],blocks:[{type:"scale",root:"A",scale:"harmMin",view:"3nps",note:"A harmonic minor, three notes per string. The gap between F and G# is the sound of the style."},{type:"scale",root:"E",scale:"phrygDom",view:"all",note:"E Phrygian dominant: the same notes as A harmonic minor, centred on E. Use it over E7."},{type:"progression",name:"Harmonic minor cadence",chords:"i iv V7 i",note:"Am, Dm, E7, Am. The G# in E7 pulls up to A."},{type:"progression",name:"Baroque circle of fifths",chords:"i iv bVII bIII bVI ii° V7 i",note:"Am, Dm, G, C, F, Bdim, E7, Am. Each root falls a fifth (or rises a fourth) to the next."},{type:"progression",name:"Diminished set-up",chords:"i bVI vii°7 V7",note:"Am, F, G#°7, E7. The diminished chord shares three notes with E7 and leads into it."},{type:"shapes",title:"Core chords in A minor",shapes:[{name:"Am",frets:"x 0 2 2 1 0"},{name:"Dm",frets:"x x 0 2 3 1"},{name:"E7",frets:"0 2 0 1 0 0"},{name:"G#°7",frets:"4 x 3 4 3 x"}],note:"Move the G#°7 shape up three frets and you still have the same chord."}]},{id:"pedal",title:"Pedal points, sequences and the band",body:"Neoclassical players borrow Baroque devices, and the **pedal point** is a favourite: one note repeats while a melody moves against it, so a single line implies both a bass and a tune. Pedal-point patterns run all through Malmsteen's playing, and heavy metal already used pedal points under its riffs, so the device feels at home.\n\nStart with an open-string pedal. The open high E sounds between fretted notes, so your fretting hand moves freely while the pick alternates down and up on one string. Once that is even, move the pedal to a fretted note, for example the 12th fret, and keep the melody within one hand position above it.\n\nA **sequence** repeats a short melodic shape on each step of the scale. Combine the two and you have the backbone of many neoclassical runs.\n\nUnderneath, the band plays speed metal, since the style combines classical elements with speed metal. A fast double-kick groove is the natural bed, with a half-time feel for slower themes.",cites:["n1","n3","n6","n14"],blocks:[{type:"tab",id:"neoclassical-pedal-sequence",title:"Open-string pedal sequence",instr:"guitar",bpm:100,grid:4,notes:[[0,1,8,1,"D"],[1,1,0,1,"U"],[2,1,7,1,"D"],[3,1,0,1,"U"],[4,1,5,1,"D"],[5,1,0,1,"U"],[6,1,7,1,"D"],[7,1,0,1,"U"],[8,1,8,1,"D"],[9,1,0,1,"U"],[10,1,10,1,"D"],[11,1,0,1,"U"],[12,1,8,1,"D"],[13,1,0,1,"U"],[14,1,7,1,"D"],[15,1,0,1,"U"],[16,1,5,1,"D"],[17,1,0,1,"U"],[18,1,4,1,"D"],[19,1,0,1,"U"],[20,1,5,1,"D"],[21,1,0,1,"U"],[22,1,7,1,"D"],[23,1,0,1,"U"],[24,1,8,1,"D"],[25,1,0,1,"U"],[26,1,4,1,"D"],[27,1,0,1,"U"],[28,1,5,4,"D,v"]],note:"Melody on the downstrokes (C, B, A, B, C, D, C, B, then A, G#, A, B, C, G#, A), open E on every upstroke. Start at 80 bpm and keep the sixteenths perfectly even."},{type:"groove",groove:{id:"neoclassical-double-kick",name:"Speed metal double kick",role:"Chorus",steps:16,beats:4,meter:"4/4",swing:0,t:{cr:"x...............",rd:"....x...x...x...",sn:"....x.......x...",kk:"xxxxxxxxxxxxxxxx"}},note:"Sixteenths on the feet, quarter notes on the ride, backbeat on the snare. Fast runs sit on top."},{type:"groove",id:"halftime",note:"For slow themes and ballad sections, drop to half time so long notes and vibrato have room."}]},{id:"picking",title:"Picking: alternate and economy",body:"Fast scale runs need a reliable pick hand, and two systems dominate.\n\n**Alternate picking** strictly alternates downstrokes and upstrokes, whatever the string. It is even and predictable, and fast, precise alternate picking is one of Malmsteen's trademarks.\n\n**Economy picking** alternates on each string but sweeps when you move to the next string in the same direction. Frank Gambale, the player most closely tied to it, works from a simple rule: an odd number of notes on a string lets the pick keep travelling the same way, and an even number lets it turn around. On an ascending three-notes-per-string scale the pattern is down-up-down, down-up-down; descending, it starts with an upstroke.\n\nIn practice the lines blur. Malmsteen often mixes legato and economy-style moves into his runs, and Jason Becker combined fast alternate picking with sweeps, legato and tapping. Try the run below both ways, slowly, and keep the system that stays clean.",cites:["n6","n7","n10","n14"],blocks:[{type:"technique",id:"alternate-picking",note:"The default for scale runs. Practise the run below with strict down-up first."},{type:"technique",id:"economy-picking",note:"Then try economy picking: down-up-down on each string, sweeping into the next."},{type:"tab",id:"neoclassical-economy-run",title:"A harmonic minor run, three notes per string",instr:"guitar",bpm:90,grid:3,notes:[[0,6,5,1,"D"],[1,6,7,1,"U"],[2,6,8,1,"D"],[3,5,5,1,"D"],[4,5,7,1,"U"],[5,5,8,1,"D"],[6,4,6,1,"D"],[7,4,7,1,"U"],[8,4,9,1,"D"],[9,3,5,1,"D"],[10,3,7,1,"U"],[11,3,9,1,"D"],[12,2,6,1,"D"],[13,2,9,1,"U"],[14,2,10,1,"D"],[15,1,7,1,"D"],[16,1,8,1,"U"],[17,1,10,1,"D"],[18,1,12,6,"U,v"]],note:"Triplets from A up to E, with the G# on the fourth and second strings. The picking shown is economy: each new string starts with a downstroke that continues the previous one."}]},{id:"arpeggios",title:"Sweep-picked and diminished arpeggios",body:"**Sweep picking** plays single notes on neighbouring strings with one smooth motion of the pick, downstrokes toward the high strings and upstrokes on the way back, while the fretting hand moves through the shape in time. It is the usual way to play fast arpeggios and needs fewer strokes than alternate picking. Premier Guitar credits players from Les Paul to Malmsteen, Jason Becker and Frank Gambale with pioneering it, and sweep-picked arpeggios are one of Malmsteen's trademarks.\n\nStart with three-string shapes. Sweep down through the strings, hammer on to the top note, pull off, and sweep back up. Where one string needs two notes, use a hammer-on or pull-off instead of a second pick stroke. Lift each finger as the next note sounds so the arpeggio does not ring like a strummed chord.\n\nThe tab runs Am, Dm, G#°7 and E. Notice the diminished shape: slide it up three frets and you play the same four notes in a new order. That symmetry lets diminished arpeggios climb the neck in minor thirds.",cites:["n1","n6","n9","n11"],blocks:[{type:"technique",id:"sweep-picking",note:"Start with three strings at a slow tempo. Clean separation matters more than speed."},{type:"tab",id:"neoclassical-sweep-arps",title:"Three-string sweeps: Am, Dm, G#°7, E",instr:"guitar",bpm:80,grid:3,notes:[[0,3,14,1,"D"],[1,2,13,1,"D"],[2,1,12,1,"D"],[3,1,17,1,"h"],[4,1,12,1,"p"],[5,2,13,1,"U"],[6,3,14,1,"U"],[7,2,15,1,"D"],[8,1,13,1,"D"],[9,1,17,1,"h"],[10,1,13,1,"p"],[11,2,15,1,"U"],[12,3,13,1,"U"],[13,2,12,1,"D"],[14,1,10,1,"D"],[15,1,13,1,"h"],[16,1,10,1,"p"],[17,2,12,1,"U"],[18,3,16,1,"U"],[19,2,15,1,"D"],[20,1,13,1,"D"],[21,1,16,1,"h"],[22,1,13,1,"p"],[23,2,15,1,"U"],[24,3,13,1,"U"],[25,2,12,1,"D"],[26,1,12,1,"D"],[27,1,16,1,"h"],[28,1,12,1,"p"],[29,2,12,1,"U"],[30,3,14,1,"U"],[31,2,13,1,"D"],[32,1,12,1,"D"],[33,1,17,3,"h,v"]],note:"Am, Dm, G#°7, the same G#°7 shape three frets higher, E, and home to Am. Sweep down, hammer, pull off, sweep back up."}]},{id:"tone",title:"Vibrato, bends and lead tone",body:"Speed is only half of this style; the long notes need to sing. Much of Malmsteen's fast passagework is violin-inspired, with Paganini and Vivaldi as models, and Blackmore's solos combine blues phrasing with classical ideas. In practice that means held notes with wide, even **vibrato**, and **bends** that land exactly on a scale note. Malmsteen's vibrato is wide but precise in pitch, helped by scalloped fingerboards and light strings.\n\nThe classic instrument is a Stratocaster-style guitar. Blackmore was one of the first rock guitarists to use a scalloped fretboard. Malmsteen has played Strats since the mid 1970s, mostly late-1960s and early-1970s models with deep scallops and single-coil-size DiMarzio pickups, through old Marshall heads turned all the way up. Shred players in general use high-gain tube amps, with distortion and compression for extra sustain.",cites:["n2","n4","n6","n13"],blocks:[{type:"technique",id:"vibrato",note:"Aim for a wide, even vibrato on every long note, like a violinist holding a phrase."},{type:"technique",id:"bends",note:"Bend to a scale note and check it against the fretted pitch. In harmonic minor, a whole-step bend from D lands on E."},{type:"tab",id:"neoclassical-vibrato-phrase",title:"Singing phrase in A harmonic minor",instr:"guitar",bpm:90,grid:4,tone:"neoclassical-lead",notes:[[0,1,12,2,""],[2,1,13,2,""],[4,1,16,4,"v"],[8,1,17,2,""],[10,1,16,2,""],[12,1,13,2,""],[14,1,12,2,""],[16,2,15,4,"b2"],[20,2,13,2,""],[22,2,12,2,""],[24,3,13,2,""],[26,2,10,6,"v"]],note:"E, F, a held G# with vibrato, A and back down; then a bend from D up to E, and a G# that resolves to a long A."},{type:"tone",id:"neoclassical-lead",name:"Singing single-coil lead",kind:"electric",guitar:"Stratocaster style, often with a scalloped fingerboard",pickups:"Single-coil-size pickups; neck position for slow melodies, bridge for fast runs",strings:"Light gauge",amp:"Cranked British-style head (vintage Marshall type)",settings:{gain:7,bass:5,mid:7,treble:6,presence:6,reverb:3,delay:4},pedals:["comp","od","delay","reverb"],demo:"neoclassical-vibrato-phrase",tips:["Malmsteen plays old Stratocasters with deep scallops, a DiMarzio HS-3 in the bridge and his own stacked single-coil-size DiMarzio models elsewhere, into vintage Marshalls set full up.","A scalloped fretboard lets you press lightly and bend or add vibrato without the fret getting in the way; Blackmore used one early on.","Light-gauge strings make wide vibrato and fast runs easier on the fretting hand.","Shred players typically pair a high-gain tube amp with distortion and compression, which add sustain.","Keep the delay low in the mix so fast runs stay clear and only held notes leave a trail. Malmsteen runs several delay units in his rig."],cites:["n2","n4","n6","n13"],note:"Switch between neck and bridge pickup while the phrase plays and listen to the vibrato."}]},{id:"form",title:"Form and melody: writing an instrumental",body:"Many neoclassical pieces are instrumentals: the golden-age shred players recorded mostly instrumental albums, and Deep Purple's *Concerto for Group and Orchestra* is cited as a key early influence on the style. So the guitar melody does the singing.\n\nWrite the theme slowly first. Use harmonic minor, land on chord tones on strong beats, and let the G# lead up to A. Then answer it: a fast run, a sweep, a pedal-point sequence. Fast passages work best as bridges between phrases a listener can hum.\n\nThe map below uses a simple plan: state a theme, contrast it, show off, and bring the theme back. It runs a half-time intro, Theme A over the circle of fifths, a contrasting Theme B, an arpeggio showcase, a short unaccompanied cadenza over the dominant, and Theme A again. For the cadenza, think of the sequenced diminished runs over a dominant chord that Wolf Marshall compares to a violin cadenza in Malmsteen's playing.",cites:["n1","n6","n12"],blocks:[{type:"form",name:"Instrumental in A minor",sections:[{type:"intro",bars:4,chords:"i iv V7 i",groove:"halftime",fill:"f-snare8"},{type:"verse",name:"Theme A",bars:8,chords:"i iv bVII bIII bVI ii° V7 i",groove:"neoclassical-double-kick",fill:"f-snare16"},{type:"chorus",name:"Theme B",bars:8,chords:"bVI - vii°7 - V7 - i -",groove:"halftime",fill:"f-build"},{type:"solo",name:"Arpeggio showcase",bars:8,chords:"i iv vii°7 V7",groove:"neoclassical-double-kick",fill:"f-toms"},{type:"bridge",name:"Cadenza",bars:4,chords:"V7 - - -",fill:"f-stop"},{type:"verse",name:"Theme A",bars:8,chords:"i iv bVII bIII bVI ii° V7 i",groove:"neoclassical-double-kick",fill:"f-snare16"},{type:"outro",bars:4,chords:"i iv V7 i",groove:"halftime",fill:"f-stop"}],note:"The cadenza has no groove: play it free, then count the band back in for the last Theme A."},{type:"callout",tone:"tip",text:"Write the theme at half speed and sing it before you play it fast. If you cannot hum it, it will not carry the piece."}]},{id:"together",title:"Put it together",body:"Put the course together as one short instrumental. Use the harmonic minor progressions as your backing, the pedal sequence and the economy run as connecting passages, the sweep arpeggios for the showcase, and the vibrato phrase as the seed of your theme.\n\nPractise every fast part at a tempo where it is perfectly clean, then raise the metronome a few beats at a time. In this style accuracy is the sound: a clean run at 100 bpm beats a smeared one at 140.",cites:["n1","n9","n10"],blocks:[{type:"checklist",items:["Play A harmonic minor three notes per string across the neck.","Play the pedal sequence cleanly at 100 bpm in sixteenths, then 120.","Choose alternate or economy picking for the scale run and stick with it for a month.","Sweep Am, Dm, G#°7 and E at 80 bpm with no notes ringing together.","Write an eight-bar theme in harmonic minor and play it with wide, even vibrato.","Arrange it: theme, contrast, showcase, cadenza, theme."]}]}]}),LEARN.course({id:"math-rock",family:"Rock",name:"Math rock",tagline:"Odd meters, tapped figures and clean, interlocking guitars that keep shifting against the beat.",level:"Intermediate",era:"Late 1980s to today",artists:["Don Caballero","Hella","Battles","Covet","TTNG","toe","tricot","LITE"],listen:["Slint – Breadcrumb Trail","Battles – Atlas","toe – Goodbye","This Town Needs Guns – Baby Beluga","American Football – Never Meant","Covet – Shibuya"],key:"D major",bpm:150,meter:"7/8",techniques:["tapping","legato","open-tunings"],sources:[{id:"m1",title:"Math rock",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Math_Rock",kind:"encyclopedia"},{id:"m2",title:"Understanding Through-Composition in Post-Rock, Math-Metal, and other Post-Millennial Rock Genres",author:"Brad Osborn",site:"Music Theory Online 17.3",year:2011,url:"https://mtosmt.org/issues/mto.11.17.3/mto.11.17.3.osborn.html",kind:"paper"},{id:"m3",title:"Read An Exclusive Excerpt From The New Book 'Math Rock' By Jeff Gomez",site:"Stereogum",year:2024,url:"https://www.stereogum.com/2257843/math-rock-jeff-gomez-excerpt/columns/sounding-board/book-club/",kind:"book"},{id:"m4",title:"A Complete Guide to Japanese Math Rock",author:"Ed Cunningham",site:"Tokyo Weekender",year:2020,url:"https://www.tokyoweekender.com/2020/02/brief-guide-japanese-math-rock/",kind:"article"},{id:"m5",title:"This Town Ain't Big Enough: This Town Needs Guns",author:"Luisa Mateus",site:"Gigwise",year:2008,url:"https://www.gigwise.com/features/43285/this-town-aint-big-enough-this-town-needs-guns",kind:"interview"},{id:"m6",title:"Don Caballero Return, Just In Time For Math-Rock's Spotlight Moment",author:"Hank Shteamer",site:"Stereogum",year:2026,url:"https://stereogum.com/2512380/don-caballero-return-just-in-time-for-math-rocks-spotlight-moment/interviews/qa",kind:"interview"},{id:"m7",title:"Covet's Yvette Young Breaks Free",author:"Joe Charupakorn",site:"Premier Guitar",year:2023,url:"https://www.premierguitar.com/artists/guitarists/yvette-young-breaks-free",kind:"interview"},{id:"m8",title:"Yvette Young: I'm really optimistic about the future of guitar",author:"Jenna Scaramanga",site:"Guitar World",year:2023,url:"https://www.guitarworld.com/features/yvette-young-covet-catharsis",kind:"interview"},{id:"m9",title:"Tapping",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Tapping",kind:"encyclopedia"},{id:"m10",title:"Polymeter",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Polymeter",kind:"encyclopedia"},{id:"m11",title:"TTNG: 'Adventure, Stamina & Anger' on Exclaim! TV",author:"Calum Slingerland",site:"Exclaim!",year:2015,url:"https://exclaim.ca/music/article/ttng-adventure_stamina_anger_on_exclaim_tv",kind:"article"},{id:"m12",title:"Never Meant: The Complete Oral History of American Football",author:"TJ Kliebhan",site:"VICE (Noisey)",year:2016,url:"https://www.vice.com/en/article/never-meant-the-complete-oral-history-of-american-football/",kind:"interview"}],study:[{title:"Math Rock (Genre: A 33 1/3 Series)",kind:"book",author:"Jeff Gomez",url:"https://bookloft.com/book/9798765103371",note:"A full history of the genre, from Slint and Don Caballero to the looping duos."},{title:"Spiderland (1991)",kind:"album",author:"Slint",note:"Named again and again as a seminal influence on math rock."},{title:"What Burns Never Returns (1998)",kind:"album",author:"Don Caballero",note:"A core instrumental record from one of the genre pioneers."},{title:"The Book About My Idle Plot on a Vague Anxiety (2005)",kind:"album",author:"toe",note:"Purely instrumental Japanese math rock built on spiralling guitars and an inventive drummer."},{title:"T H E (2013)",kind:"album",author:"tricot",note:"Pop-leaning math rock that revived the technical craft of the genre."},{title:"Animals (2008)",kind:"album",author:"This Town Needs Guns",note:"The UK reference: intricate guitar work with shared vocals."},{title:"Mirrored (2007)",kind:"album",author:"Battles",note:"Loops and odd meters from an ex-Don Caballero guitarist and an ex-Helmet drummer."},{title:"Effloresce (2018)",kind:"album",author:"Covet",note:"Open tunings, tapping and layered delay in a modern instrumental band."}],steps:[{id:"sound",title:"The sound: odd meters and clean, tangled guitars",body:"Math rock is a style of alternative and indie rock built on complex rhythms: odd time signatures, irregular stops and starts, counterpoint and extended chords. Bands are usually small and the guitar takes a central role.\n\nKing Crimson's *Red* and *Discipline* and Slint's *Spiderland* are its seminal influences. In the early 1990s Don Caballero's Ian Williams brought odd meters into that band, and songs were built from repeating sections pasted together, with abrupt shifts creating tension. Polvo, Bitch Magnet and Hella are part of the same US story.\n\nThe style travelled. In the UK, Oxford's This Town Needs Guns (now TTNG) built their sound on Tim Collis's intricate fingerpicked guitar. Japan has one of the strongest scenes, with toe, tricot, LITE and The Cabs. Covet, led by Yvette Young, is at the forefront of the US scene, and Young names Midwest emo bands such as American Football alongside toe as major influences.",cites:["m1","m3","m4","m5","m7","m11"],blocks:[{type:"callout",tone:"history",text:"The name began as a joke. Matt Sweeney of Chavez said a friend would sit unmoved through a song and then rate it with a calculator. Some well-known bands still keep the label at arm's length: early TTNG said they had math elements without being a math-rock band.",cites:["m1","m5"]}]},{id:"harmony",title:"Harmony: extended chords and open strings",body:"Math rock harmony leans on **extended chords**: major sevenths, ninths, added notes and sharp elevenths. Try voicing them so open strings ring against fretted notes, which suits riffs that loop for a long time.\n\nSome players reach for **open tunings**. Midwest emo and math-rock bands led Yvette Young to alternate tunings, and her signature Ibanez guitars ship tuned F A C G B E. Open D (D A D F# A D) is a friendly place to start: the open strings already form a D major chord, so any fretted note sits against a ringing drone.\n\nWrite chord loops that avoid a strong V to I pull. Imaj9 to vi9, or IVmaj7#11 to V6/9, keeps the harmony floating, and the rhythm section supplies the tension.",cites:["m1","m7","m8"],blocks:[{type:"progression",name:"Extended-chord loop",chords:"Imaj9 vi9 IVmaj7#11 V6/9",note:"Dmaj9, Bm9, Gmaj7#11, A6/9. Nothing resolves hard, so the loop can run for a long time."},{type:"progression",name:"Second riff loop",chords:"IVmaj9 V6/9 iii7 vi9",note:"Gmaj9, A6/9, F#m7, Bm9. Starting away from the tonic makes this a natural B section."},{type:"technique",id:"open-tunings",note:"Try Open D for the 7/8 riff in the next step. Retune the 6th, 3rd, 2nd and 1st strings."},{type:"tuning",name:"Open D",notes:"D2 A2 D3 F#3 A3 D4",note:"Strum the open strings: a D major chord. Fretted notes now sit against a drone."}]},{id:"rhythm",title:"Rhythm: 7/8, 5/4 and shifting accents",body:"Where most rock stays in 4/4, math rock shifts between meters such as 5/4, 7/8, 11/8 and 13/8. The trick is grouping. A bar of 7/8 is seven eighth notes, felt here as 2+2+3. A bar of 5/4 is ten eighths, felt here as 3+3+2+2. Count the groups and put an accent at the start of each one.\n\nDrums carry much of the complexity. Brad Osborn's study of math-metal describes rhythms that rarely settle into grooves with a recognisable meter, set against stable passages that work as releases.\n\n**Polymeter** and **polyrhythm** add another layer. In a polymeter the bar lengths differ but the beat stays the same, so parts drift apart and line up again. Yvette Young describes a Covet passage with her guitar in five, the drums in four and the bass in three. A three-note figure repeated over sixteenths in 4/4 does the same thing on a small scale: its accent lands somewhere new each time until the pattern comes round.",cites:["m1","m2","m7","m10"],blocks:[{type:"groove",groove:{id:"math-rock-78",name:"7/8 groove (2+2+3)",role:"Verse",steps:14,beats:3.5,meter:"7/8",swing:0,t:{hh:"X.x.X.x.X.x.x.",sn:"....x.......x.",kk:"x.....x.x....."}},note:"Accented hats mark the three groups. Kick on group one, snare on group two, kick and snare inside the long group."},{type:"tab",id:"math-rock-78-riff",title:"7/8 riff in Open D",instr:"guitar",tuning:"D2 A2 D3 F#3 A3 D4",bpm:150,grid:2,beats:3.5,ring:!0,tone:"math-rock-clean",notes:[[0,6,0,4,"acc"],[1,3,7,2,""],[2,4,7,2,"acc"],[3,1,0,2,""],[4,5,2,3,"acc"],[5,3,5,2,""],[6,2,4,2,""],[7,5,0,4,"acc"],[8,3,7,2,""],[9,4,4,2,"acc"],[10,1,0,2,""],[11,6,5,3,"acc"],[12,3,5,2,""],[13,1,4,2,""]],note:"Two bars of 7/8 in eighth notes, grouped 2+2+3. Accented notes start each group. Let everything ring."},{type:"groove",groove:{id:"math-rock-54",name:"5/4 groove (3+3+2+2)",role:"Bridge & feels",steps:20,beats:5,meter:"5/4",swing:0,t:{rd:"X.x.x.X.x.x.X.x.X.x.",sn:"......x.........x...",kk:"x.........x.x......."}},note:"Ride accents mark the groups of three, three, two and two."},{type:"groove",groove:{id:"math-rock-displaced",name:"Three over four",role:"Bridge & feels",steps:16,beats:4,meter:"4/4",swing:0,t:{hh:"x.x.x.x.x.x.x.x.",sn:"....x.......x...",kk:"x..x..x..x..x..x"}},note:"Hats and snare stay in 4/4 while the kick repeats every three sixteenths, so it lands somewhere new each beat."}]},{id:"techniques",title:"Tapping, interlocking parts and loops",body:"Two-hand **tapping** frets and sounds a note in one motion, so your pick hand can play notes on the fretboard. Its roots go back to Paganini's violin playing and early banjo and ukulele players, and Eddie Van Halen popularised it in rock in the late 1970s. Math-rock guitarists use tapping and loop pedals as everyday tools.\n\nThe basic cell is tap, pull off, hammer on: three notes from one string. Repeat it over a sixteenth-note pulse and it becomes a three-against-four figure that keeps shifting against the beat.\n\nGuitarists also build **interlocking parts**, where two players each take half of a line and fill each other's gaps. American Football's Steve Holmes has said he and Mike Kinsella wrote their guitar arrangements together, and he lists Steve Reich among his influences. Loop pedals such as the Akai Headrush and Boss RC-20 and RC-300 let one player layer several parts live. Don Caballero started looping on a Headrush after losing a guitarist in 1999, and Ian Williams carried that loop-driven approach into Battles.",cites:["m1","m3","m6","m9","m12"],blocks:[{type:"technique",id:"tapping",note:"In math rock, tapping is a rhythm tool as much as a lead tool. Keep the taps exactly on the grid."},{type:"technique",id:"legato",note:"Every tapped cell depends on strong pull-offs and hammer-ons from the fretting hand."},{type:"tab",id:"math-rock-tap-cell",title:"Three-note tapping cell over 4/4",instr:"guitar",bpm:120,grid:4,tone:"math-rock-clean",notes:[[0,1,17,1,"t"],[1,1,10,1,"p"],[2,1,14,1,"h"],[3,1,17,1,"t"],[4,1,10,1,"p"],[5,1,14,1,"h"],[6,1,17,1,"t"],[7,1,10,1,"p"],[8,1,14,1,"h"],[9,1,17,1,"t"],[10,1,10,1,"p"],[11,1,14,1,"h"],[12,1,17,1,"t"],[13,1,10,1,"p"],[14,1,14,1,"h"],[15,1,17,1,"t"],[16,1,19,1,"t"],[17,1,10,1,"p"],[18,1,14,1,"h"],[19,1,19,1,"t"],[20,1,10,1,"p"],[21,1,14,1,"h"],[22,1,19,1,"t"],[23,1,10,1,"p"],[24,1,14,1,"h"],[25,1,19,1,"t"],[26,1,10,1,"p"],[27,1,14,1,"h"],[28,1,19,1,"t"],[29,1,10,1,"p"],[30,1,14,1,"h"],[31,1,19,1,"t"]],note:"Fretting hand holds frets 10 and 14 on the high E. Tap 17 for D major (A, D, F#), then move the tap to 19 for B minor (B, D, F#). The tap lands on a new part of the beat each time."},{type:"tab",id:"math-rock-54-interlock",title:"Interlocking parts in 5/4",instr:"guitar",bpm:150,grid:2,beats:5,ring:!0,notes:[[0,5,5,3,"acc"],[1,2,7,1,""],[2,1,5,1,""],[3,4,4,3,"acc"],[4,1,9,1,""],[5,2,10,1,""],[6,5,2,2,"acc"],[7,1,7,1,""],[8,4,4,2,"acc"],[9,1,10,1,""],[10,6,3,3,"acc"],[11,2,8,1,""],[12,1,7,1,""],[13,5,5,3,"acc"],[14,1,10,1,""],[15,2,7,1,""],[16,5,0,2,"acc"],[17,1,9,1,""],[18,4,2,2,"acc"],[19,1,5,1,""]],note:"Two bars of 5/4 grouped 3+3+2+2. Guitar 1 plays the accented low notes on each group; guitar 2 fills every gap on the top strings. Loop one part and play the other over it."}]},{id:"tone",title:"Tone: clean, compressed and ambient",body:"Yvette Young's rig pairs amps such as a Vox AC30 and a Roland JC-40 with several delay pedals. Clean or lightly driven tones keep every tapped note and extended chord clear, and dirt is there for contrast: LITE set heavy, gritty riffs against delicate plucked passages.\n\nTapping has limited dynamics and timbre, which is why compression is often used with it. Delay and reverb fill the space around short, clipped notes, and Yvette Young layers both. A looper turns one guitarist into an ensemble.\n\nA simple chain: compressor first, a light overdrive you can step on for loud sections, then delay and reverb into a clean amp with plenty of headroom.",cites:["m4","m7","m8","m9"],blocks:[{type:"tone",id:"math-rock-clean",name:"Clean with sparkle",kind:"electric",guitar:"Any electric with a clear, bright voice",pickups:"Single-coil or a lower-output humbucker",strings:"10s (check tension if you use open tunings)",amp:"Clean amp with plenty of headroom",settings:{gain:2,bass:4,mid:5,treble:7,presence:6,reverb:3,delay:3},pedals:["comp","od","delay","reverb"],demo:"math-rock-tap-cell",tips:["Put a compressor first. Tapped notes have limited dynamics, and compression evens out taps, pull-offs and hammer-ons.","Keep the amp clean so every note of an extended chord or tapped figure stays clear.","Save the overdrive for contrast, the way LITE move between gritty riffs and delicate plucked passages.","Layer delay and reverb lightly behind clipped notes, as Yvette Young does, and keep the delay quieter than the dry signal.","Add a looper (Boss RC-20 or RC-300 style) to layer interlocking parts on your own."],cites:["m3","m4","m7","m8","m9"],note:"Play the tapping cell with the compressor off, then on, and listen to the pull-offs match the taps."}]},{id:"form",title:"Song form: built from sections",body:"Many math-rock songs skip conventional verses and choruses. Don Caballero built songs from repeating sections pasted together, with abrupt shifts creating tension, and Brad Osborn describes math-metal forms as strings of rhythmically interesting riffs that seldom return.\n\nGive each section its own meter or groove and use the changes as your drama. A 7/8 riff can give way to a 4/4 section that feels like release, then a 5/4 interlude, then a loop build that layers parts until the band crashes back in. Osborn hears the same move in math-metal: stable passages work as releases after rhythmic turbulence.\n\nVocal bands such as TTNG fit this onto a song shape with sung sections. The map below uses section names you can relabel as verse and chorus if you add vocals.",cites:["m2","m3","m5","m11"],blocks:[{type:"form",name:"Sectional math-rock map",sections:[{type:"intro",name:"Tapped intro",bars:4,chords:"Imaj9 vi9",groove:"math-rock-displaced",fill:""},{type:"verse",name:"Riff A (7/8)",bars:8,chords:"Imaj9 vi9 IVmaj7#11 V6/9",groove:"math-rock-78",fill:"f-snare8"},{type:"chorus",name:"Release (4/4)",bars:8,chords:"IVmaj9 V6/9 iii7 vi9",groove:"rock-ride",fill:"f-toms"},{type:"bridge",name:"Interlude (5/4)",bars:8,chords:"Imaj9 - IVmaj7#11 -",groove:"math-rock-54",fill:"f-snare16"},{type:"verse",name:"Riff A (7/8)",bars:8,chords:"Imaj9 vi9 IVmaj7#11 V6/9",groove:"math-rock-78",fill:"f-stop"},{type:"bridge",name:"Loop build",bars:8,chords:"vi9 - IVmaj7#11 -",groove:"build-tom",fill:"f-build"},{type:"chorus",name:"Release (4/4)",bars:8,chords:"IVmaj9 V6/9 iii7 vi9",groove:"rock-ride",fill:"f-toms"},{type:"outro",bars:4,chords:"Imaj9 -",groove:"math-rock-displaced",fill:"f-stop"}],note:"Every section changes meter or feel. The 4/4 release lands harder because of the odd-meter sections around it."}]},{id:"melody",title:"Vocals or instruments: carrying the melody",body:"Math rock splits into instrumental and vocal acts. Many key bands, such as Don Caballero and Hella, are fully instrumental, and toe's debut album is purely instrumental. When there are vocals, the voice is usually treated as one more instrument in the mix, and the lyrics are not the focus.\n\nIf you write words, let the band's odd meter shape them. A sung line in 4/4 floating over a 7/8 riff creates its own polymeter. Short, conversational phrases that start after the downbeat leave room for the guitars.\n\nIf you stay instrumental, give the lead guitar a clear melody: a tapped figure or a high line that returns, so the listener has something to hold on to through all the meter changes.",cites:["m1","m4","m6"],blocks:[{type:"lyrics",section:"verse",prompt:"Write a short verse of conversational lines, as if you were halfway through a thought. Start each line after the downbeat so the guitars stay in front.",tips:["Keep lines uneven in length; they do not need to fill the bar.","Sing in a steady 4/4 phrase over the 7/8 riff and let the two drift apart and meet again.","Repeat one image or phrase so the listener has an anchor."]}]},{id:"together",title:"Put it together",body:"Build a two-minute piece: a tapped intro, a 7/8 riff, a 4/4 release, a 5/4 interlude and a loop build back into the main riff. Write it in standard tuning or try Open D.\n\nPractise every odd-meter part with a metronome clicking eighth notes and count the groups out loud until your accents land without thinking. Then record one guitar part, loop it, and write the part that interlocks with it.\n\nKeep the tempo modest at first. A steady groove in 7/8 at 120 bpm teaches your hands more than a shaky one at 150, and the speed comes once the counting is automatic.",cites:["m1","m3"],blocks:[{type:"checklist",items:["Count 7/8 as 2+2+3 and 5/4 as 3+3+2+2 out loud with a metronome.","Write one riff in 7/8 or 5/4 with an accent on each group.","Learn the tap, pull, hammer cell and move it through two chords.","Try Open D and write a riff that uses its open strings.","Write two interlocking parts, or loop one and play the other over it.","Lay out your sections with a meter or feel change between each."]}]}]});